import { serve } from "https://deno.land/std@0.224.0/http/server.ts";
import { createClient } from "https://esm.sh/@supabase/supabase-js@2";
import { getProductionConfig, isFeatureEnabled } from "../_shared/production_config_cache.ts";

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers":
    "authorization, x-client-info, apikey, content-type",
};

const supabase = createClient(
  Deno.env.get("SUPABASE_URL")!,
  Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!,
);

serve(async (req) => {
  if (req.method === "OPTIONS") {
    return new Response("ok", {
      headers: corsHeaders,
    });
  }

  // Hoisted out of the try block (Phase 5 F5: logging-only) so the catch-all error handler below
  // can include them for diagnosis -- no change to any value, validation, or control flow, only to
  // where these two references are declared.
  let order_id: any;
  let rider_id: any;

  try {
    const body = await req.json();
    order_id = body.order_id;
    rider_id = body.rider_id;

    if (!order_id || !rider_id) {
      return Response.json(
        {
          success: false,
          message: "order_id and rider_id required",
        },
        {
          status: 400,
          headers: corsHeaders,
        },
      );
    }

    // =====================================================
    // AUTH
    // =====================================================
    const token = req.headers.get("Authorization")?.replace("Bearer ", "");

    if (!token) {
      return Response.json(
        { success: false, message: "Missing auth token" },
        { status: 401, headers: corsHeaders },
      );
    }

    // Auth resolution and the order fetch are independent of each other's result (order_id was
    // already validated above, before either starts) -- run concurrently instead of serially.
    // Same two checks, same precedence (auth checked first below, exactly as before, so an
    // invalid token still always yields 401 regardless of order_id), same responses either way;
    // only removes one round trip's worth of serial wait per call on this rider-accept hot path.
    const [{ data: authData, error: authError }, { data: order, error: orderError }] =
      await Promise.all([
        supabase.auth.getUser(token),
        supabase.from("orders").select("*").eq("id", order_id).single(),
      ]);

    if (authError || !authData.user) {
      return Response.json(
        { success: false, message: "Unauthorized" },
        { status: 401, headers: corsHeaders },
      );
    }

    // =====================================================
    // FETCH ORDER
    // =====================================================
    if (orderError || !order) {
      return Response.json(
        {
          success: false,
          message: "Order not found",
        },
        {
          status: 404,
          headers: corsHeaders,
        },
      );
    }

    // Idempotent retries still pass server-side ownership/invariant checks.
    // A new acceptance retains the existing feature gates before the RPC.
    if (!(order.rider_id === rider_id && order.order_status === "accepted")) {
      const productionConfig = await getProductionConfig(supabase);
      if (order.order_type === "ride") {
        if (
          !isFeatureEnabled(productionConfig, "local_rides_enabled") ||
          !isFeatureEnabled(productionConfig, "ride_booking_enabled")
        ) {
          return Response.json(
            { success: false, message: "Ride booking is temporarily unavailable. Please try again later." },
            { status: 503, headers: corsHeaders },
          );
        }
      } else if (order.order_type === "local_parcel") {
        if (!isFeatureEnabled(productionConfig, "parcel_enabled")) {
          return Response.json(
            { success: false, message: "Parcel booking is temporarily unavailable. Please try again later." },
            { status: 503, headers: corsHeaders },
          );
        }
      } else if (order.order_type === "intercity_ride" || order.order_type === "intercity_parcel") {
        if (!isFeatureEnabled(productionConfig, "intercity_enabled")) {
          return Response.json(
            { success: false, message: "Intercity booking is temporarily unavailable. Please try again later." },
            { status: 503, headers: corsHeaders },
          );
        }
      }
    }

    // One database transaction owns every acceptance write. Never fall back to
    // separate assignment/order updates: a missing or failed RPC must fail closed.
    const { data: acceptance, error: acceptanceError } = await supabase.rpc(
      "claim_order_assignment_atomic",
      { p_order_id: order_id, p_rider_id: rider_id, p_actor_user_id: authData.user.id },
    );
    if (acceptanceError || !acceptance) {
      const code = acceptanceError?.code;
      const retryable = ["40001", "40P01", "55P03", "57014"].includes(code ?? "");
      const claimedByOtherWriter = code === "23505" &&
        acceptanceError?.message?.includes("rider_assignments_one_accepted_per_order");
      console.error("accept-order atomic transaction failed", { order_id, rider_id, code });
      return Response.json(
        { success: false, message: claimedByOtherWriter ? "Order already accepted by another rider" : retryable ? "Acceptance is busy. Please retry." : "Unable to accept order", retryable },
        { status: claimedByOtherWriter ? 409 : retryable ? 503 : 500, headers: corsHeaders },
      );
    }
    const { http_status, ...responseBody } = acceptance;
    return Response.json(responseBody, { status: http_status, headers: corsHeaders });
  } catch (error) {
    console.error("ACCEPT ORDER ERROR:", { order_id, rider_id, error });
    // A malformed request body (req.json() throwing) is a client mistake, not a server failure --
    // was previously indistinguishable from a genuine crash once it fell into this catch-all 500.
    if (error instanceof SyntaxError) {
      return Response.json(
        { success: false, message: "Malformed request body" },
        { status: 400, headers: corsHeaders },
      );
    }
    return Response.json(
      {
        success: false,
        message: "Internal server error",
      },
      {
        status: 500,
        headers: corsHeaders,
      },
    );
  }
});

// Shared helper: getProductionConfig / isFeatureEnabled
//
// In-memory TTL cache for the single active `production_config` row, scoped to this Deno isolate --
// same pattern as getDispatchConfig (dispatch_config_cache.ts): Supabase Edge Function isolates are
// reused across nearby-in-time invocations, so a short module-scope TTL cache avoids re-querying a
// 1-row table on every single request while never risking config staler than the TTL.
//
// This is the server-side half of the Phase 1 production control system. The Flutter client enforces
// feature flags for UI visibility (see FeatureFlags/ProductionConfigService); this file is what the
// safest, most central Edge Functions (create-order, create-payment, send-push-notification) check
// before actually performing the operation a flag controls, so a flag is never "just a UI toggle".

// deno-lint-ignore no-explicit-any
type ProductionConfig = Record<string, any>;

const TTL_MS = 30_000;

let cached: ProductionConfig | null = null;
let cachedAt = 0;
let inFlight: Promise<ProductionConfig | null> | null = null;

/**
 * Returns the active production_config row, refetching via `supabase` only if the cache is empty or
 * older than 30s. Concurrent invocations that land in this isolate during a refresh share the same
 * in-flight request instead of each firing their own duplicate query.
 *
 * Returns null if the row cannot be fetched (e.g. transient DB error) -- callers must treat a null
 * config as "no restriction" (fail open), never as "everything disabled", so a config outage cannot
 * itself take down ride booking / payments / notifications. This mirrors the Flutter client's own
 * documented fail-open policy for the same reason.
 */
export async function getProductionConfig(
  // deno-lint-ignore no-explicit-any
  supabase: any,
): Promise<ProductionConfig | null> {
  const now = Date.now();
  if (cached && now - cachedAt < TTL_MS) {
    return cached;
  }
  if (inFlight) {
    return inFlight;
  }

  inFlight = (async () => {
    try {
      const { data } = await supabase
        .from("production_config")
        .select("*")
        .eq("is_active", true)
        .single();
      cached = data ?? null;
      cachedAt = Date.now();
      return cached;
    } catch (_e) {
      // Fail open: keep serving the previous cached value (even if stale) rather than treating a
      // transient fetch error as "config says disabled".
      return cached;
    }
  })();

  try {
    return await inFlight;
  } finally {
    inFlight = null;
  }
}

/**
 * Reads a named boolean flag off a (possibly null) config row, defaulting to `true` (enabled) when
 * the config is unavailable or the column is missing/null -- never fail closed on a config outage.
 */
export function isFeatureEnabled(
  config: ProductionConfig | null,
  key: string,
  defaultValue = true,
): boolean {
  if (!config) return defaultValue;
  const value = config[key];
  return typeof value === "boolean" ? value : defaultValue;
}

